create extension if not exists pgcrypto;
create table if not exists public.bot_settings(id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references auth.users(id) on delete cascade,discord_webhook_url text not null default '',enabled boolean not null default false,steam_enabled boolean not null default true,epic_enabled boolean not null default true,free_only boolean not null default false,min_discount integer not null default 30 check(min_discount between 0 and 100),interval_hours integer not null default 6 check(interval_hours in(1,3,6,8,12,24)),message_template text not null default E'🎮 **{title}**\\n🏷️ {price} · -{discount}%\\n🔗 {url}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.deals(id uuid primary key default gen_random_uuid(),external_id text not null,title text not null,store text not null check(store in('Steam','Epic Games')),image_url text not null default '',url text not null,original_price numeric(10,2) not null default 0,sale_price numeric(10,2) not null default 0,discount_percent integer not null default 0,is_free boolean not null default false,end_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store,external_id));
create table if not exists public.publication_logs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,external_id text not null,store text not null,title text not null,status text not null check(status in('sent','error','skipped')),message text not null default '',created_at timestamptz not null default now());
create index if not exists deals_created_at_idx on public.deals(created_at desc);create index if not exists logs_owner_created_idx on public.publication_logs(owner_id,created_at desc);create index if not exists logs_dedupe_idx on public.publication_logs(owner_id,store,external_id,status);
alter table public.bot_settings enable row level security;alter table public.deals enable row level security;alter table public.publication_logs enable row level security;
drop policy if exists settings_owner_select on public.bot_settings;create policy settings_owner_select on public.bot_settings for select to authenticated using(auth.uid()=owner_id);
drop policy if exists settings_owner_insert on public.bot_settings;create policy settings_owner_insert on public.bot_settings for insert to authenticated with check(auth.uid()=owner_id);
drop policy if exists settings_owner_update on public.bot_settings;create policy settings_owner_update on public.bot_settings for update to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists deals_authenticated_read on public.deals;create policy deals_authenticated_read on public.deals for select to authenticated using(true);
drop policy if exists logs_owner_read on public.publication_logs;create policy logs_owner_read on public.publication_logs for select to authenticated using(auth.uid()=owner_id);
-- A chave service_role só pode ser usada no servidor, nunca no navegador.
